    Flattens a nested list into a single-dimensional list.

    Example:
    >>> flatten_list([[1, 2], [3, [4, 5]], 6])
    [1, 2, 3, 4, 5, 6]
    """
    def _flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from _flatten(item)
            else:
                yield item

    return list(_flatten(nested_list))

