def flatten_list(nested_list):
    """
    Flatten a nested list of arbitrary depth.

    Args:
    nested_list (list): A list which may contain other nested lists.

    Returns:
    list: A flattened version of the nested list.
    """
    def recursive_flatten(lst):
        """Recursively flatten a nested list."""
        for item in lst:
            if isinstance(item, list):
                yield from recursive_flatten(item)
            else:
                yield item

    return list(recursive_flatten(nested_list))

